import re

base = "/private/tmp/claude-501/-Users-kevingalligan-devel-framejob/9cfd7405-83ec-4caa-905f-7b97a20f2cc9/scratchpad/inventory/feature-fixes/hdr.json"
src = "/Users/kevingalligan/devel/framejob/.claude/worktrees/help-docs/docs/site/src/data/features.json"
fix = json.load(open(base))
data = json.load(open(src))
rows = [f for s in data["sections"] if s["id"] == "hdr" for f in s["features"]]
ids = {r["id"]: r for r in rows}
print("rows", len(rows), "updates", len(fix["updates"]), "remove", len(fix["remove"]))
seen = set()
for u in fix["updates"]:
    assert u["id"] in ids, u["id"]
    assert u["id"] not in seen, u["id"]
    seen.add(u["id"])
    for k, v in u.items():
        if k != "id" and ids[u["id"]].get(k, "") == v:
            print("NO CHANGE", u["id"], k)
for r in fix["remove"]:
    assert r["id"] in ids and r["id"] not in seen, r["id"]
bad = re.compile(r"refus|the op\b|the core|answers|ticks|powerful|seamless|simply|just\b|easily", re.I)
removed = {r["id"] for r in fix["remove"]}
merged = []
for r in rows:
    if r["id"] in removed:
        continue
    m = dict(r)
    m.update(next((u for u in fix["updates"] if u["id"] == r["id"]), {}))
    merged.append(m)
for m in merged:
    if len(m["summary"]) > 140:
        print("LONG", len(m["summary"]), m["id"])
    if bad.search(m["summary"]) or bad.search(m["name"]):
        print("WORD", m["id"], m["name"], "|", m["summary"])

